// View Position (0018,5101) -> SNOMED CT (same CID 4010 concepts), used when there is no View
// Code Sequence. The oblique (RLO, LLO) and decubitus (RLD, LLD) terms are left out: CID 4010
// has no single "lateral oblique" concept per side, and decubitus is a patient position.
conceptmap "cm-viewPosition" {
  prefix s = "http://dicom.nema.org/resources/ontology/DCM"
  prefix t = "http://snomed.info/id"
  s:AP == t:399348003     // antero-posterior
  s:PA == t:272479007     // postero-anterior
  s:LL == t:399173006     // left lateral
  s:RL == t:399198007     // right lateral
}

