uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-Content" alias Content as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-ImagingProcedure" alias ImagingProcedure as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-ImagingSeries" alias ImagingSeries as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-BodyPosition" alias BodyPosition as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-ImagingFrame" alias ImagingFrame as target

imports "http://research.balgrist.ch/fhir2sphn/StructureMap/Utils"

group imagingProcedure(source imagingStudy: ImagingStudy, source bundle: Bundle, target content: Content) <<types>>{
    // Empty studies are not mapped. A study is skipped unless it has all three of:
    // - started (SPHN hasStartDateTime is 1..1), with no fallback to series[].started;
    // - a study modality in cm-acquisitionModality (SPHN hasCode is 1..*), keep this list in
    //   sync with the concept map;
    // - at least one in-scope series, i.e. one the series rules below would emit (same DCM
    //   list as the non-MR series rule).
    imagingStudy where started.exists()
        and modality.where(code in ('XA' | 'CT' | 'MR' | 'US' | 'RF' | 'DX' | 'CR')).exists()
        and series.where(modality.code in ('AR' | 'BDUS' | 'BI' | 'BMD' | 'CFM' | 'CR' | 'CT' | 'DG' | 'DMS' | 'DX' | 'ECG' | 'EEG' | 'EMG' | 'EOG' | 'EPS' | 'ES' | 'GM' | 'HD' | 'IO' | 'IVOCT' | 'IVUS' | 'KER' | 'LEN' | 'LS' | 'MG' | 'MR' | 'NM' | 'OAM' | 'OCT' | 'OP' | 'OPM' | 'OPT' | 'OPTBSV' | 'OPTENF' | 'OPV' | 'OSS' | 'PA' | 'POS' | 'PT' | 'PX' | 'RESP' | 'RF' | 'RG' | 'RTIMAGE' | 'SM' | 'SRF' | 'TG' | 'US' | 'VA' | 'XA' | 'XC')).exists()
      -> content.ImagingProcedure = create('ImagingProcedure') as imgproc then {
        imagingStudy.meta as m then refSourceSystem(m, imgproc);
        imagingStudy.identifier as id where id.use = 'secondary' -> imgproc.id = ('ImagingProcedure/' & %id.value);
        imagingStudy.started as startDate -> imgproc.hasStartDateTime = startDate;
        // One SPHN Code (iri + termid) per mappable modality; hasCode is 1..* on
        // ImagingProcedure. CR and DX share a target, so a study listing both would get the
        // code twice; the Balgrist export carries one modality per study, so no dedup.
        imagingStudy.modality as modality where code in ('XA' | 'CT' | 'MR' | 'US' | 'RF' | 'DX' | 'CR') -> translate(modality, '#cm-acquisitionModality') as cm,
            imgproc.hasCode as code, code.termid = (%cm.code), code.iri = (%cm.system & '/' & %cm.code) "hasCode";

        // The SPHN modality-specific series classes (CT, MR, PET, X-Ray) are flattened into
        // SPHN-ImagingSeries in the logical model, so both branches create the same type and
        // record the real SPHN class in target_concept. Only the MR branch carries
        // hasBodyPosition, which the body-position-modality-only invariant permits.
        imagingStudy.series as srcSeries where srcSeries.modality.code = 'MR' -> imgproc.hasImagingSeries = create('ImagingSeries') as tgtSeries, tgtSeries.target_concept = 'https://biomedit.ch/rdf/sphn-schema/sphn#MagneticResonanceImagingSeries' then {
            // Guarded: without this, every MR series produces an empty BodyPosition whose
            // hasCode satisfies neither branch of code-iri-or-codingSystem.
            srcSeries where extension.where(extension.where(url = 'tag').valueString = '00185100').exists() -> tgtSeries.hasBodyPosition = create('BodyPosition') as tgtBodyPosition then {
                // SPHN requires hasSourceSystem (1..*) on BodyPosition too; taken from the study.
                imagingStudy.meta as m then refSourceSystem(m, tgtBodyPosition) "bodyPositionSourceSystem";
                bundle -> tgtBodyPosition then subjectPseudoIdentifier(bundle, tgtBodyPosition) "bodyPositionSubject";
                srcSeries -> tgtBodyPosition then bodyPosition(srcSeries, tgtBodyPosition) "bodyPositionCode";
            } "bodyPosition";
            // SPHN requires hasSourceSystem (1..*) on every series; taken from the study.
            imagingStudy.meta as m then refSourceSystem(m, tgtSeries) "seriesSourceSystemMR";
            bundle -> tgtSeries then subjectPseudoIdentifier(bundle, tgtSeries) "seriesSubjectMR";
            srcSeries -> tgtSeries then imagingSeries(srcSeries, tgtSeries) "commonSeries";
            // One frame per listed instance; frame classes are flattened like the series ones.
            srcSeries.instance as srcInstance -> tgtSeries.hasImagingFrame = create('ImagingFrame') as tgtFrame, tgtFrame.target_concept = 'https://biomedit.ch/rdf/sphn-schema/sphn#MagneticResonanceImagingFrame' then imagingFrame(srcInstance, srcSeries, imagingStudy, tgtFrame) "framesMR";
        } "mapSeriesMR";
        // Series whose modality is outside the DCM part of SPHN's hasImagingModalityCode union
        // (e.g. OT, SR, PR) are out of scope and skipped entirely. MR is in the list, so the
        // MR branch above needs no such filter.
        imagingStudy.series as srcSeries where srcSeries.modality.code != 'MR' and srcSeries.modality.code in ('AR' | 'BDUS' | 'BI' | 'BMD' | 'CFM' | 'CR' | 'CT' | 'DG' | 'DMS' | 'DX' | 'ECG' | 'EEG' | 'EMG' | 'EOG' | 'EPS' | 'ES' | 'GM' | 'HD' | 'IO' | 'IVOCT' | 'IVUS' | 'KER' | 'LEN' | 'LS' | 'MG' | 'MR' | 'NM' | 'OAM' | 'OCT' | 'OP' | 'OPM' | 'OPT' | 'OPTBSV' | 'OPTENF' | 'OPV' | 'OSS' | 'PA' | 'POS' | 'PT' | 'PX' | 'RESP' | 'RF' | 'RG' | 'RTIMAGE' | 'SM' | 'SRF' | 'TG' | 'US' | 'VA' | 'XA' | 'XC') -> imgproc.hasImagingSeries = create('ImagingSeries') as tgtSeries, tgtSeries.target_concept = 'https://biomedit.ch/rdf/sphn-schema/sphn#ImagingSeries' then {
            imagingStudy.meta as m then refSourceSystem(m, tgtSeries) "seriesSourceSystem";
            bundle -> tgtSeries then subjectPseudoIdentifier(bundle, tgtSeries) "seriesSubject";
            srcSeries -> tgtSeries then imagingSeries(srcSeries, tgtSeries) "defaultSeries";
            srcSeries.instance as srcInstance -> tgtSeries.hasImagingFrame = create('ImagingFrame') as tgtFrame, tgtFrame.target_concept = 'https://biomedit.ch/rdf/sphn-schema/sphn#ImagingFrame' then imagingFrame(srcInstance, srcSeries, imagingStudy, tgtFrame) "framesDefault";
        } "mapSeriesDefault";

    } "ImagingProcedure";
}

/*
What to map and from where:
DataFile: discuss
EndDateTime: Not direct mappable, must be derivated
ImagingFrame: Instance from ImagingStudy.series.instance
ImagingModalityCode: Modality field from ImagingStudy.series 
MedicalDevice: inside extension from ImagingStudy.series
NumberOfFrames: (should be part of instance, and not series?)
ProtocolName: check the meaning
SourceSystem: discuss
SubjectPseudoIdentifier: set on every series and BodyPosition (SPHN 1..1); not on the
  ImagingProcedure, where the connector injects it and rejects an explicit one
*/

// Bundle Patient -> hasSubjectPseudoIdentifier. SPHN requires it (1..1) on ImagingSeries, the
// CT/MR/PET/X-Ray series and BodyPosition. The connector only injects it on top-level concepts,
// so these nested ones must carry it, as a reference to the root SubjectPseudoIdentifier that
// BundleToLoopSphn.map builds from the same Patient.identifier (<system>_<deid>). Any other id
// would be a second, incomplete SubjectPseudoIdentifier.
// ImagingStudy.subject is deliberately not used: the pipeline's bundles carry it as a resolved
// literal reference (Patient/<id>) or not at all (KLI_31), while the bundle has one Patient.
group subjectPseudoIdentifier(source bundle: Bundle, target tgt) {
    bundle.entry as entry then {
        entry.resource as patient where $this.ofType(FHIR.Patient) then {
            patient.identifier first as identifier -> tgt.hasSubjectPseudoIdentifier = create('Reference') as ref, ref.reference = (%identifier.system & '_' & %identifier.value) "subjectRef";
        } "patient";
    } "entry";
}

group imagingSeries(source series, target tgtSeries: ImagingSeries) {
    series.uid as uid -> tgtSeries.id = ('ImagingSeries/' & %uid);
    series.description as seriesDesc -> tgtSeries.hasDescription = seriesDesc;
    series.started as seriesStartdate -> tgtSeries.hasStartDateTime = seriesStartdate;
    // The DICOM modality is kept as a dcm: code in SPHN Code shape (MR series are pinned to
    // dcm:MR). The calling rules only pass series whose modality SPHN allows.
    series.modality as modality -> tgtSeries.hasImagingModalityCode as code, code.termid = (%modality.code), code.iri = ('http://dicom.nema.org/resources/ontology/DCM/' & %modality.code) "modalityCode";
    series.numberOfInstances as seriesNFrames -> tgtSeries.hasNumberOfFrames as nFrames then {
        seriesNFrames -> nFrames.id = uuid(), nFrames.hasValue = seriesNFrames, nFrames.hasUnit as unit then imaging_unit_number(nFrames, unit) "unit_rule";
    } "valueQuantity_fhirQuantity";

}

// Reads DICOM Patient Position (0018,5100), which is the tag actually populated on the
// series in the test data. The previously used Patient Orientation Code Sequence
// (0054,0410) occurs on only one series in the whole bundle, and that one is DX, not MR.
//
// The code is written in the iri + termid shape. SPHN's hasCode union on BodyPosition holds
// only terminology classes (dcm:1268xx, snomed:9851009) and no sphn:Code, so the
// hasCodingSystemAndVersion + hasIdentifier shape is rejected there.
group bodyPosition(source series, target tgtBodyPosition: BodyPosition) {
    series.extension as dicomExt
      where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM'
        and extension.where(url = 'tag').valueString = '00185100'
      -> tgtBodyPosition.hasCode as bodyPositionCode then {
        dicomExt -> evaluate(dicomExt, extension.where(url = 'value').valueString) as posTerm,
            translate(posTerm, '#cm-patientPosition') as cm,
            bodyPositionCode.termid = (%cm.code),
            bodyPositionCode.iri = (%cm.system & '/' & %cm.code) "bodyPosition_rule";
    } "hasCode";
}

// series.instance -> ImagingFrame. Only uid is on the instance itself; the frame attributes
// come from the DICOM tags on the series (the export flags them imaging_frame_concept), which
// are the header of the one instance the export lists per series. With more than one instance
// that header cannot be attributed to a frame, so the frames then carry only their id.
group imagingFrame(source instance, source series, source imagingStudy: ImagingStudy, target tgtFrame: ImagingFrame) {
    instance.uid as uid -> tgtFrame.id = ('ImagingFrame/' & %uid) "frameId";
    series as s where instance.count() = 1 then {
        s -> tgtFrame then imagingFrameType(s, tgtFrame) "type";
        s -> tgtFrame then imagingFrameContentQualification(s, tgtFrame) "contentQualification";
        s -> tgtFrame then imagingFrameStartDateTime(s, imagingStudy, tgtFrame) "startDateTime";
        s -> tgtFrame then imagingFrameDimensions(s, tgtFrame) "dimensions";
        s -> tgtFrame then imagingFrameProjection(s, tgtFrame) "projection";
        s -> tgtFrame then imagingFrameBodySite(s, tgtFrame) "bodySite";
        s -> tgtFrame then imagingFrameCompression(s, tgtFrame) "compression";
        s -> tgtFrame then imagingFrameMetric(s, tgtFrame) "metric";
    } "header";
}

// Image Type (0008,0008) -> hasType. Only values 1-3 are mapped: 1 (ORIGINAL / DERIVED) and
// 2 (PRIMARY / SECONDARY) are fixed by DICOM, 3 holds the modality's defined terms; values 4+
// are vendor-specific and may collide with SPHN names by accident (e.g. DERIVED, PARALLEL).
// Values outside cm-imagingFrameType (empty, M, RAD, ...) are dropped.
group imagingFrameType(source series, target tgtFrame: ImagingFrame) {
    series.extension as dicomExt
      where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM'
        and extension.where(url = 'tag').valueString = '00080008'
      then {
        dicomExt where extension.where(url = 'value').valueString.split('|')[0].length() > 0
          -> evaluate(dicomExt, extension.where(url = 'value').valueString.split('|')[0].upper().replace(' ', '').replace('_', '')) as term
          then imagingFrameTypeTerm(term, tgtFrame) "value1";
        dicomExt where extension.where(url = 'value').valueString.split('|')[1].length() > 0
          -> evaluate(dicomExt, extension.where(url = 'value').valueString.split('|')[1].upper().replace(' ', '').replace('_', '')) as term
          then imagingFrameTypeTerm(term, tgtFrame) "value2";
        dicomExt where extension.where(url = 'value').valueString.split('|')[2].length() > 0
          -> evaluate(dicomExt, extension.where(url = 'value').valueString.split('|')[2].upper().replace(' ', '').replace('_', '')) as term
          then imagingFrameTypeTerm(term, tgtFrame) "value3";
    } "imageType";
}

// translate leaves cm empty for a value outside the map, so the value is checked against the
// map's source keys first (same list as cm-imagingFrameType, keep the two in sync).
group imagingFrameTypeTerm(source term, target tgtFrame: ImagingFrame) {
    term where $this in (
            '2DIMAGING' | '3DRENDERING' | 'ABDOMINAL' | 'ADDITION' | 'ANGIO' | 'ANGIOTIME' | 'ASL' | 'ATTENUATION' | 'AXIAL' | 'BIPLANEA' |
            'BIPLANEB' | 'BLANK' | 'BREAST' | 'CARDIAC' | 'CARDIACCASCORE' | 'CARDIACCTA' | 'CARDIACGATED' | 'CARDRESPGATED' | 'CHEST' | 'CINE' |
            'COLORDOPPLER' | 'COLORMMODE' | 'COLORPOWERMODE' | 'CORNEALTOPO' | 'CWDOPPLER' | 'DENSITYMAP' | 'DERIVED' | 'DIFFUSION' | 'DIFFUSIONMAP' | 'DIVISION' |
            'DIXON' | 'DRR' | 'DYNAMIC' | 'EFFATOMICNUM' | 'ELECTRONDENSITY' | 'EMISSION' | 'ENDOCAVITARY' | 'ENDORECTAL' | 'ENDOVAGINAL' | 'ENERGYPROPWT' |
            'EPICARDIAL' | 'FETALHEART' | 'FILTERED' | 'FLOWENCODED' | 'FLUENCE' | 'FLUIDATTENUATED' | 'FLUOROSCOPY' | 'FMRI' | 'GATED' | 'GATEDTOMO' |
            'GENERATED2D' | 'GYNECOLOGY' | 'HIGHENERGY' | 'IMAGEADDITION' | 'INTRACARDIAC' | 'INTRAOPERATIVE' | 'INTRAVASCULAR' | 'LABEL' | 'LOCALIZER' | 'LONGITUDINAL' |
            'LOWENERGY' | 'MASKED' | 'MATFRACTIONAL' | 'MATMODIFIED' | 'MATREMOVED' | 'MATSPECIFIC' | 'MATVALUEBASED' | 'MAXIMUM' | 'MAXIP' | 'MEAN' |
            'MEDIAN' | 'METABOLITEMAP' | 'MINIMUM' | 'MINIP' | 'MIXED' | 'MMODE' | 'MODULUSSUBTRACT' | 'MONTAGE' | 'MOTION' | 'MPR' |
            'MULTIECHO' | 'MULTIPLICATION' | 'MUSCULOSKELETAL' | 'NEONATALHEAD' | 'NONE' | 'NONPARALLEL' | 'OBSTETRICAL' | 'ONH' | 'OPHTHALMIC' | 'ORIGINAL' |
            'OTHER' | 'OVERVIEW' | 'PARALLEL' | 'PEDIATRIC' | 'PELVIC' | 'PERFUSION' | 'PHASEMAP' | 'PHASESUBTRACT' | 'PORTAL' | 'POSTBIOPSY' |
            'POSTBIOPSYMINUS' | 'POSTBIOPSYPLUS' | 'POSTCONTRAST' | 'POSTFIRE' | 'POSTFIREMINUS' | 'POSTFIREPLUS' | 'POSTMARKER' | 'POSTMARKERMINUS' | 'POSTMARKERPLUS' | 'PRECONTRAST' |
            'PREFIRE' | 'PREFIREMINUS' | 'PREFIREPLUS' | 'PRIMARY' | 'PROJECTIONIMAGE' | 'PROTONDENSITY' | 'PWDOPPLER' | 'QUANTITY' | 'RADIOGRAPH' | 'REALTIME' |
            'RECONGATEDTOMO' | 'RECONTOMO' | 'REFERENCE' | 'RESAMPLED' | 'RESPGATED' | 'REST' | 'RETINALTHICK' | 'RETROPERITONEAL' | 'SCROTAL' | 'SECONDARY' |
            'SIMULATOR' | 'SINGLEPLANE' | 'SMALLPARTS' | 'SPATIALLYRELATEDFRAMES' | 'SPECTROSCOPY' | 'STATIC' | 'STDDEVIATION' | 'STEREOL' | 'STEREOMINUS' | 'STEREOPLUS' |
            'STEREOR' | 'STEREOSCOUT' | 'STIR' | 'STRESS' | 'SUBTRACTION' | 'T1' | 'T1MAP' | 'T2' | 'T2MAP' | 'T2STAR' |
            'TAGGING' | 'TEE' | 'TEMPERATURE' | 'THUMBNAIL' | 'THYROID' | 'TISSUECHARACTERIZATION' | 'TOF' | 'TOMO' | 'TOMOPROJ' | 'TOMOSCOUT' |
            'TOMOSYNTHESIS' | 'TRANSCRANIAL' | 'TRANSMISSION' | 'TTE' | 'USBIOPSY' | 'VASCULAR' | 'VELOCITY' | 'VELOCITYMAP' | 'VMI' | 'VOLUME' |
            'WHOLEBODY')
      -> translate(term, '#cm-imagingFrameType') as cm,
        tgtFrame.hasType as frameType, frameType.iri = (%cm.system & '#' & %cm.code) "frameType";
}

// Content Qualification (0018,9004) -> hasContentQualification.
group imagingFrameContentQualification(source series, target tgtFrame: ImagingFrame) {
    series.extension as dicomExt
      where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM'
        and extension.where(url = 'tag').valueString = '00189004'
        and extension.where(url = 'value').valueString in ('PRODUCT' | 'RESEARCH' | 'SERVICE')
      -> evaluate(dicomExt, extension.where(url = 'value').valueString) as term,
        translate(term, '#cm-imagingFrameContentQualification') as cm,
        tgtFrame.hasContentQualification as qualification, qualification.iri = (%cm.system & '#' & %cm.code) "contentQualification";
}

// Acquisition DateTime (0008,002A), else Acquisition Date (0008,0022) + Time (0008,0032),
// -> hasStartDateTime. Both are brought to one DICOM DT string (YYYYMMDDHHMMSS[.F][&ZZXX]);
// partial values (no seconds) are skipped.
group imagingFrameStartDateTime(source series, source imagingStudy: ImagingStudy, target tgtFrame: ImagingFrame) {
    series.extension as dicomExt
      where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM'
        and extension.where(url = 'tag').valueString = '0008002A'
      -> evaluate(dicomExt, extension.where(url = 'value').valueString) as dt
      then dicomDateTime(dt, imagingStudy, tgtFrame) "acquisitionDateTime";
    series where extension.where(extension.where(url = 'tag').valueString = '0008002A').empty()
        and extension.where(extension.where(url = 'tag').valueString = '00080022').exists()
        and extension.where(extension.where(url = 'tag').valueString = '00080032').exists()
      -> evaluate(series, extension.where(extension.where(url = 'tag').valueString = '00080022').extension.where(url = 'value').valueString
          & extension.where(extension.where(url = 'tag').valueString = '00080032').extension.where(url = 'value').valueString) as dt
      then dicomDateTime(dt, imagingStudy, tgtFrame) "acquisitionDateAndTime";
}

// DICOM DT -> dateTime. FHIR requires an offset once a time is given: the value's own offset
// is used if present, else the study's (DICOM local time, same site and day as the study).
group dicomDateTime(source dt, source imagingStudy: ImagingStudy, target tgtFrame: ImagingFrame) {
    dt where $this.matches('^[0-9]{14}([.][0-9]{1,6})?[+-][0-9]{4}$')
      -> tgtFrame.hasStartDateTime = (%dt.replaceMatches('^([0-9]{4})([0-9]{2})([0-9]{2})([0-9]{2})([0-9]{2})([0-9]{2})([.][0-9]{1,6})?([+-][0-9]{2})([0-9]{2})$', '$1-$2-$3T$4:$5:$6$7$8:$9')) "ownOffset";
    dt where $this.matches('^[0-9]{14}([.][0-9]{1,6})?$')
        and %imagingStudy.started.toString().matches('^.*([+-][0-9]{2}:[0-9]{2}|Z)$')
      -> tgtFrame.hasStartDateTime = (%dt.replaceMatches('^([0-9]{4})([0-9]{2})([0-9]{2})([0-9]{2})([0-9]{2})([0-9]{2})([.][0-9]{1,6})?$', '$1-$2-$3T$4:$5:$6$7')
          & %imagingStudy.started.toString().replaceMatches('^.*([+-][0-9]{2}:[0-9]{2}|Z)$', '$1')) "studyOffset";
}

// Rows (0028,0010), Columns (0028,0011), Slice Thickness (0018,0050), Spacing Between Slices
// (0018,0088) and Pixel Spacing (0028,0030) -> hasImageDimensions. Zero values (a slice
// thickness of 0 on projection images) carry no dimension and are dropped; the guard on the
// whole concept checks the same, so no empty ImageDimensions is created. hasNumberOfSlices has
// no per-frame source (Number of Frames is series-level and goes to hasNumberOfFrames).
group imagingFrameDimensions(source series, target tgtFrame: ImagingFrame) {
    series where extension.where(url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM'
            and ((extension.where(url = 'tag').valueString in ('00280010' | '00280011' | '00180050' | '00180088') and extension.where(url = 'value').value > 0)
              or (extension.where(url = 'tag').valueString = '00280030' and extension.where(url = 'value').valueString.matches('^[0-9]+([.][0-9]+)?[|][0-9]+([.][0-9]+)?$')))).exists()
      -> tgtFrame.hasImageDimensions as dims, dims.id = uuid() then {
        series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00280010' then {
            dicomExt.extension as v where url = 'value' then {
                v.value as n where $this > 0 -> dims.hasNumberOfRows as q then imagingCountQuantity(n, q) "rowsValue";
            } "rowsExt";
        } "rows";
        series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00280011' then {
            dicomExt.extension as v where url = 'value' then {
                v.value as n where $this > 0 -> dims.hasNumberOfColumns as q then imagingCountQuantity(n, q) "columnsValue";
            } "columnsExt";
        } "columns";
        series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00180050' then {
            dicomExt.extension as v where url = 'value' then {
                v.value as n where $this > 0 -> dims.hasSliceThickness as q then imagingMillimetreQuantity(n, q) "thicknessValue";
            } "thicknessExt";
        } "sliceThickness";
        series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00180088' then {
            dicomExt.extension as v where url = 'value' then {
                v.value as n where $this > 0 -> dims.hasSliceSpacing as q then imagingMillimetreQuantity(n, q) "spacingValue";
            } "spacingExt";
        } "sliceSpacing";
        // Pixel Spacing is "row spacing|column spacing": value 1 is the distance between the
        // centres of adjacent rows, which is SPHN's hasRowSpacing.
        series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00280030'
            and extension.where(url = 'value').valueString.matches('^[0-9]+([.][0-9]+)?[|][0-9]+([.][0-9]+)?$')
          -> dims.hasPixelDimensions as px, px.id = uuid() then {
            dicomExt -> evaluate(dicomExt, extension.where(url = 'value').valueString.split('|')[0].toDecimal()) as r,
                px.hasRowSpacing as q then imagingMillimetreQuantity(r, q) "rowSpacing";
            dicomExt -> evaluate(dicomExt, extension.where(url = 'value').valueString.split('|')[1].toDecimal()) as c,
                px.hasColumnSpacing as q then imagingMillimetreQuantity(c, q) "columnSpacing";
        } "pixelSpacing";
    } "imageDimensions";
}

group imagingCountQuantity(source n, target q) {
    n -> q.id = uuid(), q.hasValue = n, q.hasUnit as unit then imaging_unit_number(n, unit) "countQuantity";
}

group imagingMillimetreQuantity(source n, target q) {
    n -> q.id = uuid(), q.hasValue = n, q.hasUnit as unit then imaging_unit_mm(n, unit) "mmQuantity";
}

// View Code Sequence (0054,0220), else View Position (0018,5101) -> hasAnatomicalProjection.
// The export flattens each sequence item to one attribute per item (CodeValue, Coding Scheme
// Designator and Code Meaning are sibling items), so the code value is looked up on its own:
// a legacy SRT / SNM3 id through cm-viewCode, or taken as is when the scheme is SCT.
// View Position is only used without a View Code Sequence; a sequence with a code outside the
// map gives no projection rather than a possibly inconsistent one from View Position.
group imagingFrameProjection(source series, target tgtFrame: ImagingFrame) {
    series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00540220' then {
        dicomExt.extension as seq where url = 'sequence' then {
            seq.extension as item where url = 'item' then {
                item.extension as attr where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00080100'
                    and extension.where(url = 'value').valueString in (
            'G-8300' | 'G-A145' | 'R-10202' | 'R-10204' | 'R-10206' | 'R-10208' | 'R-10210' | 'R-10212' |
            'R-10214' | 'R-10216' | 'R-10220' | 'R-10224' | 'R-10226' | 'R-10228' | 'R-10230' | 'R-10232' |
            'R-10234' | 'R-10236' | 'R-10238' | 'R-10241' | 'R-10242' | 'R-10244' | 'R-10246' | 'R-10248' |
            'R-10250' | 'R-10252' | 'R-10254' | 'R-10256' | 'R-10257' | 'R-102C1' | 'R-102C2' | 'R-102C3' |
            'R-102C4' | 'R-102C5' | 'R-102C6' | 'R-102C7' | 'R-102C8' | 'R-102CD' | 'R-40782' | 'R-40783' |
            'R-40810' | 'R-40888' | 'R-40985')
                  -> evaluate(attr, extension.where(url = 'value').valueString) as c,
                    translate(c, '#cm-viewCode') as cm,
                    tgtFrame.hasAnatomicalProjection as proj, proj.id = uuid(),
                    proj.hasCode as code, code.termid = (%cm.code), code.iri = (%cm.system & '/' & %cm.code) "legacyCode";
                item.extension as attr where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00080100'
                    and extension.where(url = 'value').valueString.matches('^[0-9]+$')
                    and %seq.extension.where(url = 'item').extension.where(extension.where(url = 'tag').valueString = '00080102').extension.where(url = 'value').valueString = 'SCT'
                  -> evaluate(attr, extension.where(url = 'value').valueString) as c,
                    tgtFrame.hasAnatomicalProjection as proj, proj.id = uuid(),
                    proj.hasCode as code, code.termid = c, code.iri = ('http://snomed.info/id/' & %c) "sctCode";
            } "item";
        } "sequence";
    } "viewCode";
    series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00185101'
        and extension.where(url = 'value').valueString in ('AP' | 'PA' | 'LL' | 'RL')
        and %series.extension.where(extension.where(url = 'tag').valueString = '00540220').empty()
      -> evaluate(dicomExt, extension.where(url = 'value').valueString) as c,
        translate(c, '#cm-viewPosition') as cm,
        tgtFrame.hasAnatomicalProjection as proj, proj.id = uuid(),
        proj.hasCode as code, code.termid = (%cm.code), code.iri = (%cm.system & '/' & %cm.code) "viewPosition";
}

// Anatomic Region Sequence (0008,2218) -> hasBodySite, with Image Laterality (0020,0062) as its
// hasLaterality. Same flattened sequence and code lookup as imagingFrameProjection. SPHN's
// BodySite requires hasCode, so a laterality without a region is not mapped.
group imagingFrameBodySite(source series, target tgtFrame: ImagingFrame) {
    series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00082218' then {
        dicomExt.extension as seq where url = 'sequence' then {
            seq.extension as item where url = 'item' then {
                item.extension as attr where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00080100'
                    and extension.where(url = 'value').valueString in (
            'R-FAB52' | 'R-FAB53' | 'R-FAB54' | 'R-FAB55' | 'R-FAB56' | 'T-04000' | 'T-11011' | 'T-11100' |
            'T-11102' | 'T-11133' | 'T-11149' | 'T-11166' | 'T-11170' | 'T-11180' | 'T-11196' | 'T-11210' |
            'T-11300' | 'T-11501' | 'T-11502' | 'T-11503' | 'T-11AD0' | 'T-11BF0' | 'T-12280' | 'T-12310' |
            'T-12340' | 'T-12410' | 'T-12700' | 'T-12710' | 'T-12730' | 'T-12750' | 'T-12770' | 'T-12980' |
            'T-13600' | 'T-14668' | 'T-15290' | 'T-15420' | 'T-15430' | 'T-15460' | 'T-15610' | 'T-15680' |
            'T-15710' | 'T-15750' | 'T-15770' | 'T-22000' | 'T-24100' | 'T-25000' | 'T-26000' | 'T-280A0' |
            'T-30000' | 'T-32000' | 'T-50007' | 'T-56000' | 'T-57000' | 'T-58000' | 'T-58200' | 'T-58400' |
            'T-58600' | 'T-59000' | 'T-59300' | 'T-59600' | 'T-59900' | 'T-60600' | 'T-60610' | 'T-61100' |
            'T-61300' | 'T-63000' | 'T-64500' | 'T-65000' | 'T-65010' | 'T-65600' | 'T-7000B' | 'T-73000' |
            'T-74000' | 'T-75000' | 'T-88920' | 'T-92000' | 'T-AA000' | 'T-AB959' | 'T-D0010' | 'T-D0146' |
            'T-D0300' | 'T-D04FF' | 'T-D0801' | 'T-D0821' | 'T-D1000' | 'T-D1100' | 'T-D1213' | 'T-D1460' |
            'T-D14AE' | 'T-D1600' | 'T-D2000' | 'T-D2010' | 'T-D2020' | 'T-D2220' | 'T-D2500' | 'T-D3300' |
            'T-D8000' | 'T-D8200' | 'T-D8500' | 'T-D8700' | 'T-D8800' | 'T-D8810' | 'T-D9000' | 'T-D9100' |
            'T-D9200' | 'T-D9400' | 'T-D9700' | 'T-D9800' | 'T-DD163')
                  -> evaluate(attr, extension.where(url = 'value').valueString) as c,
                    translate(c, '#cm-anatomicRegion') as cm,
                    tgtFrame.hasBodySite as site, site.id = uuid(),
                    site.hasCode as code, code.termid = (%cm.code), code.iri = (%cm.system & '/' & %cm.code)
                  then imagingFrameLaterality(series, site) "legacyCode";
                item.extension as attr where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00080100'
                    and extension.where(url = 'value').valueString.matches('^[0-9]+$')
                    and %seq.extension.where(url = 'item').extension.where(extension.where(url = 'tag').valueString = '00080102').extension.where(url = 'value').valueString = 'SCT'
                  -> evaluate(attr, extension.where(url = 'value').valueString) as c,
                    tgtFrame.hasBodySite as site, site.id = uuid(),
                    site.hasCode as code, code.termid = c, code.iri = ('http://snomed.info/id/' & %c)
                  then imagingFrameLaterality(series, site) "sctCode";
            } "item";
        } "sequence";
    } "anatomicRegion";
}

group imagingFrameLaterality(source series, target site) {
    series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00200062'
        and extension.where(url = 'value').valueString in ('L' | 'R' | 'B')
      -> evaluate(dicomExt, extension.where(url = 'value').valueString) as l,
        translate(l, '#cm-imageLaterality') as cm,
        site.hasLaterality as lat, lat.id = uuid(),
        lat.hasCode as code, code.termid = (%cm.code), code.iri = (%cm.system & '/' & %cm.code) "laterality";
}

// Lossy Image Compression (0028,2110) = 01 -> hasAlgorithm (type LossyCompression), with the
// ratio (0028,2112) and method (0028,2114). 00 only says the image was never lossy compressed,
// not that it was compressed losslessly, so it gives no algorithm. Ratio and method are taken
// only when single-valued (one compression step). The DICOM method terms are the SPHN
// individual names without underscores (ISO_10918_1 -> ISO109181).
group imagingFrameCompression(source series, target tgtFrame: ImagingFrame) {
    series where extension.where(url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00282110' and extension.where(url = 'value').valueString = '01').exists()
      -> tgtFrame.hasAlgorithm as alg, alg.id = uuid(),
        alg.hasType as algType, algType.iri = 'https://biomedit.ch/rdf/sphn-schema/sphn/individual#LossyCompression' then {
        series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00282112' then {
            dicomExt.extension as v where url = 'value' then {
                v.value as r where $this > 0 -> alg.hasRatio as q then imagingCountQuantity(r, q) "ratioValue";
            } "ratioExt";
        } "ratio";
        series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00282114'
            and extension.where(url = 'value').valueString in ('ISO_10918_1' | 'ISO_13818_2' | 'ISO_14495_1' | 'ISO_14496_10' | 'ISO_15444_1' | 'ISO_15444_15' | 'ISO_18181_1' | 'ISO_23008_2')
          -> evaluate(dicomExt, extension.where(url = 'value').valueString.replace('_', '')) as m,
            alg.hasMethod as method, method.iri = ('https://biomedit.ch/rdf/sphn-schema/sphn/individual#' & %m) "method";
    } "lossy";
}

// Rescale Type (0028,1054) = HU -> hasImagingMetric with type code dcm:112031 (Attenuation
// Coefficient, whose unit in DICOM CID 7180 is the Hounsfield unit). SPHN's UCUM units have no
// [hnsf'U], so hasUnit is left out. US (unspecified) and PVAL say nothing about the quantity.
group imagingFrameMetric(source series, target tgtFrame: ImagingFrame) {
    series.extension as dicomExt where url = 'https://research.balgrist.ch/HDR/fhir/StructureDefinition/DICOM' and extension.where(url = 'tag').valueString = '00281054'
        and extension.where(url = 'value').valueString = 'HU'
      -> tgtFrame.hasImagingMetric as metric, metric.id = uuid(),
        metric.hasTypeCode as code, code.termid = '112031', code.iri = 'http://dicom.nema.org/resources/ontology/DCM/112031' "hounsfield";
}
